wb = openpyxl.load_workbook('./materials/FinancialStatementFY26Q4.xlsx', data_only=False)
ws = wb['Segment Results']
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    vals = []
    for c in row:
        v = c.value
        if v is not None:
            vals.append(f"{c.coordinate}={v!r}")
    if vals:
        print(' | '.join(vals))
